import{z as A,x as n,o,c as l,q as p,j as c,D as e,d as B,s as r,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"微操作缓存","description":"","frontmatter":{"title":"微操作缓存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/uop-cache.md","filePath":"cs/uop-cache.md","lastUpdated":1791413859000}'),i={name:"cs/uop-cache.md"};function d(u,a,h,C,D,m){const t=n("Mermaid");return o(),l("div",null,[a[2]||(a[2]=p('<h1 id="微操作缓存" tabindex="-1">微操作缓存 <a class="header-anchor" href="#微操作缓存" aria-label="Permalink to &quot;微操作缓存&quot;">​</a></h1><div class="epigraph"><p>变长宏指令译成定长微操作的代价很高；把已经译好的 uop 按热路径存起来，命中时取指不再走长度扫描。</p><footer>—— 据 Rotenberg, Bennett, and Smith, Trace Cache, MICRO 1996；Intel 对 uop cache 的公开描述 整理</footer></div><p><a href="/cs/fetch-decode-width">上一课</a>把前端带宽钉成供给上限，并点名变长译码是热点。本课不重做边界扫描。缺口是：<strong>用一块小的、按 uop 组织的 cache 记住最近译过的指令，命中则绕过传统译码器。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>x86 核每拍要给重命名输送 4–6 个 uop，长度译码与微码协助在频率上很痛。热循环可能只有几十条宏指令，却被反复译码。缺口不是再加一条预译码流水，而是<strong>把「PC → uop 序列」缓存下来</strong>，用 SRAM 命中代替组合译码。</p><p><span class="marginnote">Trace cache 存的是动态执行痕迹，可跨越宏指令与分支。Intel Sandy Bridge 起公开的 DSB（decoded stream buffer / uop cache）更接近「按 IP 对齐的已译码 uop」，命中则 MITE 译码器睡觉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>uop cache：索引取自指令指针（可虚拟），行内存若干 uop、下一块指针、是否以分支结束。命中：每拍从该结构弹出最多 \\(D_{\\text{uop}}\\) 个已译码 uop 进重命名，I-cache 与长度译码不参与。缺失：走普通取指/译码，填入 uop cache。自修改代码或 icache 作废时同步清空。</p>',8)),(o(),c(s,null,{default:e(()=>[r(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IP%5B%22%E6%8C%87%E4%BB%A4%E6%8C%87%E9%92%88%22%5D%20--%3E%20UC%5B%22uop%20cache%22%5D%0A%20%20UC%20--%3E%7C%22%E5%91%BD%E4%B8%AD%22%7C%20REN%5B%22%E7%9B%B4%E6%8E%A5%E9%87%8D%E5%91%BD%E5%90%8D%22%5D%0A%20%20UC%20--%3E%7C%22%E7%BC%BA%E5%A4%B1%22%7C%20MITE%5B%22%E9%95%BF%E5%BA%A6%E8%AF%91%E7%A0%81%20%2B%20%E5%BE%AE%E7%A0%81%22%5D%0A%20%20MITE%20--%3E%20FILL%5B%22%E5%A1%AB%20uop%20cache%22%5D%0A%20%20MITE%20--%3E%20REN%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与 I-cache 的包含关系：uop cache 是译码后的旁路，不替代指令页的一致性；SMC 必须两边都看到。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[B("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"前端每拍实际能送多少 uop，取决于行边界与分支预测共同决定的一连串检查：",-1)),(o(),c(s,null,{default:e(()=>[r(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20BR%5B%22%E5%88%86%E6%94%AF%E9%A2%84%E6%B5%8B%E7%BB%99%E5%87%BA%E4%B8%8B%E4%B8%80%E5%9D%97%20IP%22%5D%20--%3E%20LOOK%7B%22uop%20cache%20%E5%91%BD%E4%B8%AD%3F%22%7D%0A%20%20LOOK%20--%3E%7C%E7%BC%BA%E5%A4%B1%7C%20MIT%5B%22MITE%20%E6%85%A2%E8%B7%AF%E5%BE%84%E8%AF%91%E7%A0%81%22%5D%0A%20%20MIT%20--%3E%20RES%5B%22%E6%9C%AC%E6%8B%8D%E4%BE%9B%E7%BB%99%E5%A4%A7%E5%B9%85%E4%B8%8B%E9%99%8D%22%5D%0A%20%20LOOK%20--%3E%7C%E5%91%BD%E4%B8%AD%7C%20EDGE%7B%22%E8%A1%8C%E5%86%85%E4%B8%8B%E4%B8%80%E4%B8%AA%E8%BE%B9%E7%95%8C%3Cbr%2F%3E%E6%98%AF%E5%88%86%E6%94%AF%3F%22%7D%0A%20%20EDGE%20--%3E%7C%E5%90%A6%7C%20POPS%5B%22%E6%95%B4%E8%A1%8C%E8%BF%9E%E7%BB%AD%E5%BC%B9%E5%87%BA%E8%87%B3%E7%AB%AF%E5%8F%A3%E5%AE%BD%E5%BA%A6%22%5D%0A%20%20POPS%20--%3E%20RN%5B%22%E9%80%81%E9%87%8D%E5%91%BD%E5%90%8D%22%5D%0A%20%20EDGE%20--%3E%7C%E6%98%AF%7C%20PR%7B%22%E9%A2%84%E6%B5%8B%E5%AF%B9%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20PR%20--%3E%7C%E5%AF%B9%7C%20JUMP%5B%22%E6%97%A0%E7%BC%9D%E8%B7%B3%E5%88%B0%E5%90%8E%E7%BB%A7%E8%A1%8C%2C%20%E7%BB%A7%E7%BB%AD%E5%BC%B9%22%5D%0A%20%20JUMP%20--%3E%20RN%0A%20%20PR%20--%3E%7C%E9%94%99%7C%20FLUSH%5B%22%E5%86%B2%E5%88%B7%E5%89%8D%E7%AB%AF%2C%20%E9%87%8D%E6%96%B0%E5%8F%96%E6%8C%87%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=p('<p>前端 CPI：热路径上译码器功耗与延迟下降，有效 \\(D\\) 接近 uop 端口宽度。冷路径、巨函数、以及 uop 行装不下的超长指令序列仍走慢路径。容量以 uop 计，不是字节：一条复杂宏指令可能占多个槽，反而降低密度。</p><p>与<a href="/cs/gshare-predictor">分支预测</a>：uop 行往往在预测分支处截断，预测准才能连续弹出。误预测仍冲刷，只是重填可能再次命中 uop cache。</p><p><span class="marginnote">容量按 uop 槽计是个容易忽视的坑：典型实现约几千个 uop，一条 <code>mov</code> 大约占 1 槽，而一条复杂的读改写宏指令可能拆成 3–4 槽。同样是 100 条宏指令的热循环，全是简单指令约占 100 槽，全是复杂指令可能吃掉 400 槽——「代码短」不等于「uop 少」。</span></p><p><span class="marginnote">直觉类比：uop cache 就是「备好的翻译稿」。原文（x86 变长指令）第一次出现时翻译员逐句现场译（MITE 慢路径），并把译文抄在本子上；下次再读到同一段，直接念译稿，翻译员去睡觉。一旦有人偷偷改了原文（自修改代码），本子必须整本作废重译。</span></p><p><span class="marginnote">常见误区：以为 uop cache 命中就能「无限连续」供给。行在预测分支处截断，若预测器摇头（预测错误），前端照样冲刷重来——uop cache 只是省掉「重新翻译」，省不掉「重新排版」。所以分支预测准是它收益的前提，两者是乘法关系不是替代关系。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把循环流缓冲当成 uop cache 的子集讲完——LSB 是「锁定一个循环的 uop 流」，下一课。也不把 GPU 的指令 cache 写成 uop cache。微码 ROM 仍服务极少见的复杂指令，不进热 cache。</p><p>后课默认：热路径可以不经宏指令译码器。更小、锁定的循环还可以连 cache 标签比较都省掉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>uop cache 缓存已译码微操作，绕过变长译码。</li><li>命中率取决于热路径大小与分支截断。</li><li>把循环锁定在更浅的缓冲里，是下一课 LSB。</li><li>出处：Rotenberg et al., <em>MICRO</em>, 1996；Intel 微结构公开文档中的 DSB。</li></ul>',10))])}const T=A(i,[["render",d]]);export{P as __pageData,T as default};
